<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\ValueObject\Holder\TenantLoginProviderDirectAccessAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantLoginProviderDirectAccessAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TenantLoginProviderDirectAccessAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that isDirectAccess returns null on a freshly created holder.
     */
    public function testDirectAccessNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderDirectAccessAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isDirectAccessAssigned());
        $this->assertNull($holder->isDirectAccess());
    }
}
class ImplWithTenantLoginProviderDirectAccessAttributeHolderUnitTest
{
    use TenantLoginProviderDirectAccessAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedDirectAccessRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultDirectAccess();
    }
}
